<?php
declare(strict_types=1);
requireRole('subject-officer');
require_once __DIR__.'/../../config/database.php';
require_once __DIR__.'/../../includes/activity.php';
$activePage='vision-camp';$errors=[];$success=(string)($_SESSION['flash_success']??'');unset($_SESSION['flash_success']);$db=database();$userId=(int)$_SESSION['user_id'];

if($_SERVER['REQUEST_METHOD']==='POST'){
 $action=(string)($_POST['action']??'create');
 if(!verifyCsrfToken((string)($_POST['csrf_token']??'')))$errors[]='Your session expired.';
 if(!$errors){try{
  if($action==='create'){
   $ds=filter_input(INPUT_POST,'ds_division_id',FILTER_VALIDATE_INT);$supplier=filter_input(INPUT_POST,'supplier_id',FILTER_VALIDATE_INT);$reason=trim((string)($_POST['justification']??''));
   if(!$ds||!$supplier)throw new RuntimeException('Select a DS Division and vendor.');
   if(mb_strlen($reason)<10||mb_strlen($reason)>1000)throw new RuntimeException('Provide a justification between 10 and 1000 characters.');
   $check=$db->prepare("SELECT COUNT(*) FROM ds_divisions ds JOIN suppliers s ON s.id=:supplier AND s.status='active' WHERE ds.id=:ds AND ds.status='active'");$check->execute(['supplier'=>$supplier,'ds'=>$ds]);if(!$check->fetchColumn())throw new RuntimeException('Division or vendor is unavailable.');
   $stmt=$db->prepare('INSERT INTO vision_camps(ds_division_id,supplier_id,justification,requested_by) VALUES(:ds,:supplier,:reason,:user)');$stmt->execute(['ds'=>$ds,'supplier'=>$supplier,'reason'=>$reason,'user'=>$userId]);$id=(int)$db->lastInsertId();$message='Vision camp sent for vendor contact approval.';
  }elseif($action==='confirm-camp'){
   $id=filter_input(INPUT_POST,'camp_id',FILTER_VALIDATE_INT);$date=(string)($_POST['proposed_date']??'');$people=filter_input(INPUT_POST,'people_identified',FILTER_VALIDATE_INT);
   if(!$id||!$people||$people<1||!DateTimeImmutable::createFromFormat('Y-m-d',$date))throw new RuntimeException('Enter a valid camp date and identified headcount.');
   $stmt=$db->prepare("UPDATE vision_camps SET proposed_date=:date,people_identified=:people,stage='awaiting-goods-release' WHERE id=:id AND requested_by=:user AND stage='vendor-approved'");$stmt->execute(['date'=>$date,'people'=>$people,'id'=>$id,'user'=>$userId]);if($stmt->rowCount()!==1)throw new RuntimeException('Camp cannot be updated at its current stage.');$message='Camp results logged and goods release approval requested.';
  }elseif($action==='progress'){
   $id=filter_input(INPUT_POST,'camp_id',FILTER_VALIDATE_INT);$attended=filter_input(INPUT_POST,'attended_count',FILTER_VALIDATE_INT);$distributed=filter_input(INPUT_POST,'distributed_count',FILTER_VALIDATE_INT);$handed=filter_input(INPUT_POST,'handed_over_count',FILTER_VALIDATE_INT);
   if(!$id||$attended===false||$distributed===false||$handed===false||$attended<1||$distributed<0||$handed<0||$distributed+$handed>$attended)throw new RuntimeException('Enter valid attendance and distribution totals.');
   $stage=($distributed+$handed)===$attended?'completed':'distribution-in-progress';$stmt=$db->prepare("UPDATE vision_camps SET attended_count=:attended,distributed_count=:distributed,handed_over_count=:handed,stage=:stage WHERE id=:id AND requested_by=:user AND stage='distribution-in-progress'");$stmt->execute(['attended'=>$attended,'distributed'=>$distributed,'handed'=>$handed,'stage'=>$stage,'id'=>$id,'user'=>$userId]);if($stmt->rowCount()!==1)throw new RuntimeException('Distribution progress cannot be updated.');$message='Vision camp distribution progress updated.';
  }else throw new RuntimeException('Invalid camp action.');
  logActivity('Vision Camps',$message,'VC-'.str_pad((string)$id,4,'0',STR_PAD_LEFT));$_SESSION['flash_success']=$message;unset($_SESSION['csrf_token']);header('Location: dashboard.php?page=vision-camp');exit;
 }catch(Throwable $e){error_log($e->getMessage());$errors[]=$e instanceof RuntimeException?$e->getMessage():'Unable to update vision camp.';}}
}

try{
 $divisions=$db->query("SELECT ds.id,ds.name ds_name,d.name district_name FROM ds_divisions ds JOIN districts d ON d.id=ds.district_id WHERE ds.status='active' ORDER BY d.name,ds.name")->fetchAll();
 $suppliers=$db->query("SELECT id,company_name FROM suppliers WHERE status='active' ORDER BY company_name")->fetchAll();
 $stmt=$db->prepare('SELECT vc.*,ds.name ds_name,d.name district_name,s.company_name,u.full_name requester_name FROM vision_camps vc JOIN ds_divisions ds ON ds.id=vc.ds_division_id JOIN districts d ON d.id=ds.district_id JOIN suppliers s ON s.id=vc.supplier_id JOIN users u ON u.id=vc.requested_by WHERE vc.requested_by=:user ORDER BY vc.id DESC');$stmt->execute(['user'=>$userId]);$rows=$stmt->fetchAll();
}catch(PDOException $e){error_log($e->getMessage());$divisions=$suppliers=$rows=[];$errors[]='Vision camp workflow is unavailable.';}
$counts=array_count_values(array_column($rows,'stage'));
$summary=[
 ['☎','Awaiting Vendor Approval',(int)($counts['awaiting-vendor-approval']??0),'Awaiting Admin'],
 ['📦','Awaiting Goods Release',(int)($counts['awaiting-goods-release']??0),'Camp completed, qty confirmed'],
 ['🚚','Distribution in Progress',(int)($counts['distribution-in-progress']??0),'Goods released, distributing'],
 ['✅','Completed',(int)($counts['completed']??0),'Fully distributed or handed over'],
];
function campStageLabel(string $stage):string{return match($stage){'awaiting-vendor-approval'=>'Awaiting Vendor Contact Approval','vendor-approved'=>'Vendor Contact Approved — Camp Pending','awaiting-goods-release'=>'Awaiting Goods Release Approval','distribution-in-progress'=>'Goods Released — Distribution in Progress','completed'=>'Completed','rejected'=>'Vendor Contact Rejected',default=>ucwords(str_replace('-',' ',$stage))};}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Vision Camp / Direct Procurement | WIDMS</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="assets/css/admin-dashboard.css" rel="stylesheet"></head><body><?php require __DIR__.'/../../includes/subject-officer-sidebar.php';?><div class="admin-shell"><header class="topbar"><div class="d-flex align-items-center gap-3"><button class="menu-button" id="menu-button">&#9776;</button><h1>Vision Camp / Direct Procurement</h1></div></header><main class="dashboard-content vision-request-page">
<?php if($success):?><div class="alert alert-success"><?=htmlspecialchars($success,ENT_QUOTES,'UTF-8')?></div><?php endif;?><?php if($errors):?><div class="alert alert-danger"><?=htmlspecialchars(implode(' ',$errors),ENT_QUOTES,'UTF-8')?></div><?php endif;?>
<section class="operation-summary-grid vision-summary-grid"><?php foreach($summary as [$icon,$label,$value,$note]):?><article class="operation-summary-card"><span><?=$icon?></span><p><?=htmlspecialchars($label,ENT_QUOTES,'UTF-8')?></p><strong><?=$value?></strong><small><?=htmlspecialchars($note,ENT_QUOTES,'UTF-8')?></small></article><?php endforeach;?></section>
<section class="admin-data-card vision-request-card"><div class="admin-data-header"><h2>👓 New Vision Camp — Step 1: Request Vendor Contact Approval</h2></div><form method="post" class="vision-request-form"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrfToken(),ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="action" value="create"><p>This is a one-time approval to contact the vendor about a possible bulk spectacles procurement. No goods or quantities are committed at this stage.</p><div class="vision-form-grid"><label>Division / DS Division *<select name="ds_division_id" required><option value="">Select division</option><?php foreach($divisions as $r):?><option value="<?=(int)$r['id']?>"><?=htmlspecialchars($r['district_name'].' Division — '.$r['ds_name'],ENT_QUOTES,'UTF-8')?></option><?php endforeach;?></select></label><label>Vendor / Company *<select name="supplier_id" required><option value="">Select vendor</option><?php foreach($suppliers as $r):?><option value="<?=(int)$r['id']?>"><?=htmlspecialchars($r['company_name'],ENT_QUOTES,'UTF-8')?></option><?php endforeach;?></select></label></div><label>Reason / Justification *<textarea name="justification" rows="3" maxlength="1000" placeholder="Explain why this Vision Camp is required..." required></textarea></label><div class="vision-form-actions"><button class="admin-primary-action">☎ Submit for Vendor Contact Approval</button><small>Admin must approve before you contact the vendor</small></div></form></section>
<section class="admin-data-card vision-list-card"><div class="admin-data-header"><h2>My Vision Camp Requests</h2></div><div class="admin-data-table-wrap"><table class="admin-data-table vision-camp-table"><thead><tr><th>ID</th><th>Division</th><th>DS Division</th><th>Vendor</th><th>Requested By</th><th>Camp Date</th><th>People Identified</th><th>Attended (✓ / H / X)</th><th>Stage</th><th>Action</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="10" class="admin-empty-row">No Vision Camp requests available.</td></tr><?php else:foreach($rows as $r):?><tr><td>VC-<?=str_pad((string)$r['id'],3,'0',STR_PAD_LEFT)?></td><td><?=htmlspecialchars($r['district_name'].' Division',ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($r['ds_name'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($r['company_name'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($r['requester_name'],ENT_QUOTES,'UTF-8')?></td><td><?=$r['proposed_date']?date('d M Y',strtotime($r['proposed_date'])):'—'?></td><td><?=$r['people_identified']??'—'?></td><td><?php if($r['attended_count']===null):?>—<?php else:?><strong class="vision-count-issued"><?=(int)$r['distributed_count']?></strong> / <strong class="vision-count-handover"><?=(int)$r['handed_over_count']?></strong> / <strong class="vision-count-missing"><?=max(0,(int)$r['attended_count']-(int)$r['distributed_count']-(int)$r['handed_over_count'])?></strong><?php endif;?></td><td><span class="vision-stage vision-stage-<?=htmlspecialchars($r['stage'],ENT_QUOTES,'UTF-8')?>"><?=htmlspecialchars(campStageLabel($r['stage']),ENT_QUOTES,'UTF-8')?></span><?php if($r['rejection_reason']):?><small class="vision-rejection"><?=htmlspecialchars($r['rejection_reason'],ENT_QUOTES,'UTF-8')?></small><?php endif;?></td><td><?php if($r['stage']==='vendor-approved'):?><details class="vision-action-details"><summary>📋 Log Camp Results</summary><form method="post"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrfToken(),ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="action" value="confirm-camp"><input type="hidden" name="camp_id" value="<?=(int)$r['id']?>"><input type="date" name="proposed_date" required><input type="number" name="people_identified" min="1" placeholder="People identified" required><button class="admin-primary-action">Submit</button></form></details><?php elseif($r['stage']==='distribution-in-progress'):?><details class="vision-action-details"><summary>📦 Continue Distribution</summary><form method="post"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrfToken(),ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="action" value="progress"><input type="hidden" name="camp_id" value="<?=(int)$r['id']?>"><input type="number" name="attended_count" min="1" placeholder="Attended" required><input type="number" name="distributed_count" min="0" placeholder="Issued" required><input type="number" name="handed_over_count" min="0" placeholder="Handed over" required><button class="admin-primary-action">Update</button></form></details><?php else:?><button class="outline-action" type="button" disabled>View</button><?php endif;?></td></tr><?php endforeach;endif;?></tbody></table></div><p class="admin-table-note">🔒 Two separate Admin approvals are required: vendor contact first, then goods release after the camp headcount is known.</p></section>
</main></div><script src="assets/js/admin-dashboard.js"></script></body></html>
